"""SCRIPT v3 take plans -> jobs/v3_<batch>.json (generated by pt_gen.py; a take that exists is never paid twice).
  python pt3_jobs.py open      the opening: hook (v3_n01-n03, ONE take, 8 takes), the laugh v3_x01, v3_t01
  python pt3_jobs.py body      every other new line + the alternate hook
  python pt3_jobs.py <name>    an extra round defined in EXTRA below
The lead's settings (binding): eleven_v4, similarity 0.75, stability 0.5 / 0.35, speed 1.0, neighbouring lines as
previous / next text; James + the driver untagged first; one short tag per sentence at most; the kid tagged only."""
import json
import sys

import pt_lib as L
import pt3_lib as V

T = V.TEXT
VO = V.VOICE


def ctx(ids):
    return " ".join(T[i].lstrip(".") for i in ids) or None


def J(folder, take, role, lines, text, stab, seed, prev, nxt, check=True, note=None):
    if check:
        exp = " ".join(T[i] for i in lines)
        d = L.word_diff(exp, text)
        assert d == [], (folder, take, d)
    j = {"folder": folder, "take": take, "voice": VO[role], "model": L.MODEL, "text": text, "stability": stab, "speed": 1.0, "seed": seed,
         "prev": ctx(prev) if isinstance(prev, list) else prev, "next": ctx(nxt) if isinstance(nxt, list) else nxt, "lines": lines, "role": role,
         "candidate": V.NAME[role].lower(), "script": "v3"}
    if note:
        j["note"] = note
    return j


HOOK = "His bag is on that train. He is not. All he did was laugh... at a finger."
HL = ["v3_n01", "v3_n02", "v3_n03"]
ALTX = "He points along an empty track. The tourist laughing at him will lose that suitcase."
AL = ["v3_a01", "v3_a02"]


def opening():
    nx = ["v3_d01", "v3_t01"]
    o = [
        J("v3_hook", "t1", "N", HL, HOOK, 0.5, 9101, None, nx),
        J("v3_hook", "t2", "N", HL, HOOK, 0.35, 9102, None, nx),
        J("v3_hook", "t3", "N", HL, HOOK, 0.5, 9103, None, nx),
        J("v3_hook", "t4", "N", HL, "[amused] His bag is on that train. [deadpan] He is not. [amused] All he did was laugh... at a finger.", 0.5, 9104, None, nx),
        J("v3_hook", "t5", "N", HL, "His bag is on that train. [deadpan] He is not. All he did was laugh... at a finger.", 0.5, 9105, None, nx),
        J("v3_hook", "t6", "N", HL, "His bag is on that train. [deadpan] He is not. All he did was laugh... at a finger.", 0.35, 9106, None, nx),
        J("v3_hook", "t7", "N", HL, "[amused] His bag is on that train. He is not. All he did was laugh... at a finger.", 0.5, 9107, None, nx),
        J("v3_hook", "t8", "N", HL, "His bag is on that train. [flatly] He is not. [amused] All he did was laugh... at a finger.", 0.5, 9108, None, nx),
    ]
    # the laugh (no words): prev / next text left out on purpose (a context line could be spoken)
    for k, (tx, st) in enumerate([("[laughing hard] Hahahaha! Ahahaha!", 0.35), ("[bursts out laughing] Ha ha ha ha ha ha!", 0.5),
                                  ("[laughs] [laughs harder]", 0.5), ("[wheezing laugh] Hahaha... hahahaha!", 0.35)]):
        o.append(J("v3_x01", f"t{k + 1}", "T", ["v3_x01"], tx, st, 9201 + k, None, None, check=False, note="laugh only, no words"))
    p, n = ["v3_d01"], ["v3_n04"]
    T1 = "He's pointing at nothing!"
    o += [J("v3_t01", "t1", "T", ["v3_t01"], "[laughing] " + T1, 0.5, 9301, p, n),
          J("v3_t01", "t2", "T", ["v3_t01"], "[laughing] " + T1, 0.35, 9302, p, n),
          J("v3_t01", "t3", "T", ["v3_t01"], "[laughs] " + T1, 0.5, 9303, p, n),
          J("v3_t01", "t4", "T", ["v3_t01"], "[laughs] " + T1, 0.35, 9304, p, n),
          J("v3_t01", "t5", "T", ["v3_t01"], "[laughing] " + T1, 0.5, 9305, p, n)]
    return o


def body():
    o = []

    def four(folder, role, lines, prev, nxt, variants, seed0):
        for k, (tx, st) in enumerate(variants):
            o.append(J(folder, f"t{k + 1}", role, lines, tx, st, seed0 + k, prev, nxt))

    t = T["v3_n04"]
    four("v3_n04", "N", ["v3_n04"], ["v3_t01"], ["v3_n05"], [(t, 0.5), (t, 0.35), ("[serious] " + t, 0.5), ("[calmly] " + t, 0.5)], 9401)
    t = T["v3_n05"]
    four("v3_n05", "N", ["v3_n05"], ["v3_n04"], ["v3_n06"], [(t, 0.5), (t, 0.35), ("[playful] " + t, 0.5), ("[cheerfully] " + t, 0.5)], 9411)
    t = "First stop. His suitcase tries to get off... and the boy's finger saves it."
    four("v3_n0608", "N", ["v3_n06", "v3_n07", "v3_n08"], ["v3_n05"], ["v3_t02"],
         [(t, 0.5), (t, 0.35), ("First stop. [alarmed] His suitcase tries to get off... [relieved] and the boy's finger saves it.", 0.5),
          ("First stop. [nervous] His suitcase tries to get off... [warmly] and the boy's finger saves it.", 0.5)], 9421)
    four("v3_n0910", "N", ["v3_n09", "v3_n10"], ["v3_t03"], ["v3_t05"],
         [("Second stop. ... It stays.", 0.5), ("Second stop. It stays.", 0.5), ("Second stop. [deadpan] It stays.", 0.5),
          ("Second stop. [deadpan] It stays.", 0.35), ("Second stop. ... It stays.", 0.35)], 9431)
    t = T["v3_n11"]
    four("v3_n11", "N", ["v3_n11"], ["v3_t06"], ["v3_n12"], [(t, 0.5), (t, 0.35), ("[thoughtful] " + t, 0.5), ("[warmly] " + t, 0.5)], 9441)
    t = T["v3_n13"]
    four("v3_n13", "N", ["v3_n13"], ["v3_n12"], ["v3_n14"], [(t, 0.5), (t, 0.35), ("[intrigued] " + t, 0.5), ("[intrigued] " + t, 0.35)], 9451)
    t = T["v3_n14"]
    four("v3_n14", "N", ["v3_n14"], ["v3_n13"], ["v3_d03"], [(t, 0.5), (t, 0.35), ("[firmly] " + t, 0.5), ("[warmly] " + t, 0.5)], 9461)
    nx = ["v3_d01", "v3_t01"]
    four("v3_alt", "N", AL, None, nx, [(ALTX, 0.5), (ALTX, 0.35), (ALTX, 0.5), ("[amused] " + ALTX, 0.5),
                                       ("He points along an empty track. [dryly] The tourist laughing at him will lose that suitcase.", 0.5)], 9471)
    t = T["v3_t02"]
    four("v3_t02", "T", ["v3_t02"], ["v3_n08"], ["v3_d02"], [("[scolding] " + t, 0.5), ("[scolding] " + t, 0.35), ("[fondly] " + t, 0.5),
                                                             ("[playfully scolding] " + t, 0.5)], 9501)
    t = T["v3_t03"]
    four("v3_t03", "T", ["v3_t03"], ["v3_d02"], ["v3_n09"], [("[laughing] " + t, 0.5), ("[laughing] " + t, 0.35), ("[amused] " + t, 0.35),
                                                             ("[cocky] " + t, 0.5)], 9511)
    t = T["v3_t06"]
    four("v3_t06", "T", ["v3_t06"], ["v3_t05"], ["v3_n11"], [("[warmly] " + t, 0.5), ("[warmly] " + t, 0.35), ("[delighted] " + t, 0.5),
                                                             ("[impressed] " + t, 0.5)], 9521)
    for k, (tx, st) in enumerate([("[giggles] Hehehe... hehe.", 0.5), ("[giggling helplessly] Hee hee hee hee!", 0.35), ("[chuckles] [giggles]", 0.5)]):
        o.append(J("v3_x02", f"t{k + 1}", "T", ["v3_x02"], tx, st, 9531 + k, None, None, check=False, note="giggle only, no words"))
    return o


def hook2():
    """round 2 of the hook, around the round-1 recipe that measured best (t8: [flatly] on 'He is not.', [amused] on the third sentence)"""
    nx = ["v3_d01", "v3_t01"]
    F = "His bag is on that train. [flatly] He is not. [amused] All he did was laugh... at a finger."
    return [
        J("v3_hook", "t9", "N", HL, F, 0.5, 9109, None, nx),
        J("v3_hook", "t10", "N", HL, F, 0.35, 9110, None, nx),
        J("v3_hook", "t11", "N", HL, "His bag is on that train. [flatly] He is not. All he did was laugh... at a finger.", 0.5, 9111, None, nx),
        J("v3_hook", "t12", "N", HL, "His bag is on that train. [deadpan] He is not. [amused] All he did was laugh... at a finger.", 0.5, 9112, None, nx),
        J("v3_hook", "t13", "N", HL, "[brightly] His bag is on that train. [flatly] He is not. [amused] All he did was laugh... at a finger.", 0.5, 9113, None, nx),
        J("v3_hook", "t14", "N", HL, F, 0.5, 9114, None, nx),
        J("v3_hook", "t15", "N", HL, "His bag is on that train. [dryly] He is not. [amused] All he did was laugh... at a finger.", 0.5, 9115, None, nx),
        J("v3_hook", "t16", "N", HL, F, 0.35, 9116, None, nx),
    ]


def round2():
    """round 2 after the measurements of round 1: 'First stop.' came out high (274-291 Hz, an announcer) in all 4 takes, the
    script wants it low and clipped; no 'What's a finger gonna do?' take ended rising; every alternate-hook take was heard
    as 'tourists' (commas = prosody only, the words are the script's)."""
    o = []
    for k, (tx, st) in enumerate([
            ("[flatly] First stop. [alarmed] His suitcase tries to get off... [relieved] and the boy's finger saves it.", 0.5),
            ("[calmly] First stop. [alarmed] His suitcase tries to get off... [warmly] and the boy's finger saves it.", 0.5),
            ("[deadpan] First stop. [worried] His suitcase tries to get off... [relieved] and the boy's finger saves it.", 0.5),
            ("[flatly] First stop. His suitcase tries to get off... and the boy's finger saves it.", 0.35)]):
        o.append(J("v3_n0608", f"t{k + 5}", "N", ["v3_n06", "v3_n07", "v3_n08"], tx, st, 9425 + k, ["v3_n05"], ["v3_t02"]))
    t = T["v3_t03"]
    for k, (tx, st) in enumerate([("[laughing] What's a finger gonna do?!", 0.5), ("[teasing] " + t, 0.5), ("[incredulous] " + t, 0.35), ("[laughing] " + t, 0.5)]):
        o.append(J("v3_t03", f"t{k + 5}", "T", ["v3_t03"], tx, st, 9515 + k, ["v3_d02"], ["v3_n09"]))
    C = "He points along an empty track. The tourist, laughing at him, will lose that suitcase."
    for k, (tx, st) in enumerate([(C, 0.5), (C, 0.35), ("He points along an empty track. [dryly] The tourist, laughing at him, will lose that suitcase.", 0.5), (C, 0.5)]):
        o.append(J("v3_alt", f"t{k + 6}", "N", AL, tx, st, 9476 + k, None, ["v3_d01", "v3_t01"]))
    return o


def alt3():
    """round 3 of the alternate hook. Round 1 (no comma): in time, but all 5 takes were heard as 'tourists'. Round 2 (two commas): heard
    right, but 'suitcase.' ends near 5.3 s (the alternate's gate: by 5.00 s). So: ONE comma (the /t/ of 'tourist' gets its release), and
    the script's gated fallback first sentence 'He points down an empty track.' (line id v3_a01f)."""
    nx = ["v3_d01", "v3_t01"]
    A = "He points along an empty track. The tourist, laughing at him will lose that suitcase."
    B = "He points down an empty track. The tourist, laughing at him will lose that suitcase."
    return [J("v3_alt", "t10", "N", AL, A, 0.5, 9480, None, nx), J("v3_alt", "t11", "N", AL, A, 0.35, 9481, None, nx),
            J("v3_altf", "t1", "N", ["v3_a01f", "v3_a02"], B, 0.5, 9482, None, nx),
            J("v3_altf", "t2", "N", ["v3_a01f", "v3_a02"], "He points down an empty track. The tourist, laughing at him, will lose that suitcase.", 0.5, 9483, None, nx)]


def t07b():
    """the reused 'Bag... gone.' (ch_t06/t4) measured as the one tone-colour outlier beside the new tourist takes (a very quiet raw take,
    dull spectrum): the lead's rule = record the line again and compare"""
    t = T["v3_t07"]
    return [J("v3_t07", f"t{k + 1}", "T", ["v3_t07"], tx, st, 9541 + k, ["v3_d03", "v3_k01"], None)
            for k, (tx, st) in enumerate([("[flatly] " + t, 0.35), ("[flatly] " + t, 0.5), ("[deadpan] " + t, 0.35), ("[defeated] " + t, 0.5)])]


def alt4():
    """round 4 of the alternate hook (2026-11-20, last round, at most 6). Measured: a comma always costs 0.3-0.45 s of breathy hold
    that is NOT true silence (the build cannot cut it): one-comma takes end 'suitcase.' at 5.27-5.28 s, two-comma 5.41 s. No-comma
    takes are in time (4.82-4.97 s) but Whisper hears 'tourists'. So: NO comma, and direction that lands the final /t/ of 'tourist'
    (a crisp / enunciating tag on the second sentence, or the word in capitals for stress)."""
    nx = ["v3_d01", "v3_t01"]
    s1 = "He points along an empty track."
    s2 = "The tourist laughing at him will lose that suitcase."
    v = [(f"{s1} [crisply] {s2}", 0.5), (f"{s1} [crisply] {s2}", 0.35), (f"{s1} The TOURIST laughing at him will lose that suitcase.", 0.5),
         (f"{s1} [enunciating] {s2}", 0.5), (f"[matter-of-fact] {s1} {s2}", 0.5), (f"{s1} The TOURIST laughing at him will lose that suitcase.", 0.35)]
    return [J("v3_alt", f"t{12 + k}", "N", AL, tx, st, 9490 + k, None, nx) for k, (tx, st) in enumerate(v)]


EXTRA = {"hook2": hook2, "round2": round2, "alt3": alt3, "t07b": t07b, "alt4": alt4}

if __name__ == "__main__":
    what = sys.argv[1]
    jobs = opening() if what == "open" else body() if what == "body" else EXTRA[what]()
    (L.HERE / "jobs").mkdir(exist_ok=True)
    (L.HERE / "jobs" / f"v3_{what}.json").write_text(json.dumps(jobs, ensure_ascii=False, indent=1), encoding="utf-8")
    print(what, len(jobs), "jobs,", sum(len(j["text"]) for j in jobs), "characters")
